#!/usr/bin/env bash
# Two-way smoke test against a GnuPG binary: keys generated by gpg in a throwaway home, then
# sign/verify (detached, inline, cleartext) and encrypt/decrypt in both directions through our sop.
# Usage: tools/oracles/gpg-messages.sh <path to the onecrypto executable or "dotnet path/to/onecrypto.dll"> <work dir>
set -u
SOP=${1:?sop command}
W=${2:?work dir}
mkdir -p "$W" && cd "$W" || exit 2
export GNUPGHOME="$W/gnupg"
rm -rf "$GNUPGHOME" && mkdir -m 700 "$GNUPGHOME"
rm -f "$W"/*.v1
sop() { $SOP sop "$@"; }
pass=0; fail=0
ok() { pass=$((pass+1)); echo "ok   $1"; }
bad() { fail=$((fail+1)); echo "FAIL $1"; }

printf 'Hello from the oracle test\nsecond line\n' > msg.txt
head -c 300000 /dev/urandom > big.bin

for spec in "rsa3072:rsa3072" "ed25519:cv25519" "nistp256:nistp256" "brainpoolP256r1:brainpoolP256r1"; do
  s=${spec%%:*}; e=${spec##*:}
  uid="$s <$s@example.org>"
  gpg --batch --quiet --passphrase '' --quick-gen-key "$uid" "$s" sign,cert 1y 2>/dev/null
  fpr=$(gpg --batch --list-keys --with-colons "$s@example.org" | awk -F: '/^fpr/{print $10; exit}')
  gpg --batch --quiet --passphrase '' --quick-add-key "$fpr" "$e" encr 1y 2>/dev/null
  gpg --batch --export "$fpr" > $s.cert
  gpg --batch --export-secret-keys "$fpr" > $s.key
  # gpg -> ours
  gpg --batch --yes --local-user "$fpr" --detach-sign -o $s.gsig msg.txt 2>/dev/null
  sop verify $s.gsig $s.cert < msg.txt > /dev/null && ok "$s verify gpg detached" || bad "$s verify gpg detached"
  gpg --batch --yes --local-user "$fpr" --sign -o $s.gsigned msg.txt 2>/dev/null
  sop inline-verify $s.cert < $s.gsigned > out.txt && cmp -s out.txt msg.txt && ok "$s inline-verify gpg" || bad "$s inline-verify gpg"
  gpg --batch --yes --local-user "$fpr" --clearsign -o $s.gclear msg.txt 2>/dev/null
  sop inline-verify $s.cert < $s.gclear > /dev/null && ok "$s inline-verify gpg cleartext" || bad "$s inline-verify gpg cleartext"
  gpg --batch --yes --trust-model always -r "$fpr" -o $s.genc --encrypt big.bin 2>/dev/null
  sop decrypt $s.key < $s.genc > dec.bin && cmp -s dec.bin big.bin && ok "$s decrypt gpg" || bad "$s decrypt gpg"
  gpg --batch --yes --trust-model always -r "$fpr" --sign --local-user "$fpr" -o $s.gencs --encrypt big.bin 2>/dev/null
  sop decrypt --verifications-out=$s.v1 --verify-with=$s.cert $s.key < $s.gencs > dec.bin && cmp -s dec.bin big.bin && [ -s $s.v1 ] && ok "$s decrypt+verify gpg" || bad "$s decrypt+verify gpg"
  # ours -> gpg
  sop sign $s.key < msg.txt > $s.osig
  gpg --batch --import $s.cert 2>/dev/null
  gpg --batch --verify $s.osig msg.txt 2>/dev/null && ok "$s gpg verifies our detached" || bad "$s gpg verifies our detached"
  sop inline-sign $s.key < big.bin > $s.osigned
  gpg --batch --yes -o dec.bin --decrypt $s.osigned 2>/dev/null && cmp -s dec.bin big.bin && ok "$s gpg verifies our inline" || bad "$s gpg verifies our inline"
  sop inline-sign --as=clearsigned $s.key < msg.txt > $s.oclear
  gpg --batch --verify $s.oclear 2>/dev/null && ok "$s gpg verifies our cleartext" || bad "$s gpg verifies our cleartext"
  for prof in rfc9580 rfc4880; do
    sop encrypt --profile=$prof --sign-with=$s.key $s.cert < big.bin > $s.oenc
    gpg --batch --yes --import $s.key 2>/dev/null
    gpg --batch --yes --pinentry-mode loopback --passphrase '' -o dec.bin --decrypt $s.oenc 2>/dev/null && cmp -s dec.bin big.bin && ok "$s gpg decrypts ours ($prof)" || bad "$s gpg decrypts ours ($prof)"
  done
done

# passwords
echo -n 'pässword' > pw.txt
gpg --batch --yes --pinentry-mode loopback --passphrase-file pw.txt --symmetric --cipher-algo AES256 -o sym.gpg big.bin 2>/dev/null
sop decrypt --with-password=pw.txt < sym.gpg > dec.bin && cmp -s dec.bin big.bin && ok "decrypt gpg password" || bad "decrypt gpg password"
for prof in rfc9580 rfc4880; do
  sop encrypt --profile=$prof --with-password=pw.txt < big.bin > sym2.gpg
  if gpg --batch --yes --pinentry-mode loopback --passphrase-file pw.txt -o dec.bin --decrypt sym2.gpg 2>gpg.err && cmp -s dec.bin big.bin; then
    ok "gpg decrypts our password message ($prof)"
  elif [ "$prof" = rfc9580 ] && grep -q 'unknown version 6' gpg.err; then
    echo "skip gpg decrypts our v6 password message (GnuPG 2.4 does not read SKESK v6)"
  else
    bad "gpg decrypts our password message ($prof)"
  fi
done
echo "passed=$pass failed=$fail"
gpgconf --kill all 2>/dev/null
[ "$fail" -eq 0 ]
